"""
    helper method which takes string of YYYY-MM-DD format, removes dashes so
    relative times can be compared for plotting
    also removes day, so we have data split by months
    """
def _get_time(string: Any) -> object {
    string = string[0:7];
    return string.replace("-", "");
}

""" Returns parent layer indices for a given layer index. """
def get_layer_parents(adjList: Any, lidx: Any) -> object {
    return [
        e[0]
        for e in adjList
        if (e[1] == lidx)
    ];
}

"""
    calculates the lennard-jones-potential of a given value x
    """
def lennard_jones_potential(x: Any) -> object {
    return (4 * ((x ** -12) - (x ** -6)));
}

